import React, { useState } from 'react';
import { Link } from 'react-router';
import '../Styles/style.css';

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);
    let contenu = null;
    if (isOpen) {
        contenu =
        <div>
            <Link to="/page1" onClick={() => setIsOpen(!isOpen)}>Page 1</Link>
            <Link to="/page2" onClick={() => setIsOpen(!isOpen)}>Page 2</Link>
        </div>
    }
    return (
        <>
            <div onClick={() => setIsOpen(!isOpen)}>
                <button
                    className={`hamburger`}
                    onClick={() => setIsOpen(!isOpen)}
                    aria-label="Menu de navigation"
                >
                    ☰
                </button>
            </div>
            <nav className="navbar" style={{ display: isOpen ? 'fixed' : 'none' }}>
                {contenu}
            </nav>

            {isOpen && <div className="menu-overlay" onClick={() => setIsOpen(!isOpen)}></div>}
        </>
    );
}
